create policy bip_tasks_teen_select on public.bip_tasks for select to authenticated using (auth.uid() = teen_id);
create policy bip_tasks_linked_parent_select on public.bip_tasks for select to authenticated using (exists (select 1 from public.parent_links pl where pl.teen_user_id = bip_tasks.teen_id and pl.parent_user_id = auth.uid() and pl.status = 'active'));
create policy bip_tasks_teen_insert on public.bip_tasks for insert to authenticated with check (auth.uid() = teen_id and auth.uid() = created_by and created_by_role = 'teen' and point_value = 0 and requires_approval = false);
create policy bip_tasks_linked_parent_insert on public.bip_tasks for insert to authenticated with check (auth.uid() = created_by and created_by_role = 'parent' and exists (select 1 from public.parent_links pl where pl.teen_user_id = bip_tasks.teen_id and pl.parent_user_id = auth.uid() and pl.status = 'active'));
create policy bip_tasks_teen_update on public.bip_tasks for update to authenticated using (auth.uid() = created_by and created_by_role = 'teen') with check (auth.uid() = created_by and created_by_role = 'teen' and teen_id = auth.uid() and point_value = 0 and requires_approval = false);
create policy bip_tasks_linked_parent_update on public.bip_tasks for update to authenticated using (auth.uid() = created_by and created_by_role = 'parent' and exists (select 1 from public.parent_links pl where pl.teen_user_id = bip_tasks.teen_id and pl.parent_user_id = auth.uid() and pl.status = 'active')) with check (auth.uid() = created_by and created_by_role = 'parent' and exists (select 1 from public.parent_links pl where pl.teen_user_id = bip_tasks.teen_id and pl.parent_user_id = auth.uid() and pl.status = 'active'));
create policy task_submissions_teen_select on public.task_submissions for select to authenticated using (auth.uid() = teen_id);
create policy task_submissions_linked_parent_select on public.task_submissions for select to authenticated using (exists (select 1 from public.parent_links pl where pl.teen_user_id = task_submissions.teen_id and pl.parent_user_id = auth.uid() and pl.status = 'active'));
